# Short factual restatements; bulk reference prose is neither copied nor published.
def summarize(i,u):
 if i in manual:return manual[i]
 if re.search('в блоке характеристик',u):return 'Во всех параметрах блока призванного существа используйте круг фактически потраченной ячейки.'
 s=u
 # Standard introductory clause is replaced with a compact threshold.
 m=re.match(r'.*?(?:используя|с помощью) ячейк[уи](?: заклинан(?:ия|ий))? (.*?),\s*',s,re.I)
 if m:s='Ячейка '+m.group(1).replace('уровня','круга').replace('уровень','круг')+': '+s[m.end():]
 for a,b in [('вы можете сделать целью','допустима цель:'),('вы можете воздействовать на','можно затронуть'),('вы можете выбрать','можно выбрать'),('вы можете','можно'),('вы создаете','создаётся'),('вы создаёте','создаётся'),('вы восстанавливаете','восстановление:'),('увеличивается на','получает прибавку'),('увеличиваются на','получают прибавку'),('за каждый уровень ячейки выше','на каждый круг сверх'),('за каждый круг ячейки выше','на каждый круг сверх'),('для каждого уровня ячейки выше','на каждый круг сверх'),('за каждые два уровня ячейки выше','на каждые два круга сверх'),('за каждые две ячейки выше','на каждые два круга сверх')]:s=s.replace(a,b)
 for a,b in [('первого','1-го'),('второго','2-го'),('третьего','3-го'),('четвёртого','4-го'),('четвертого','4-го'),('пятого','5-го'),('шестого','6-го'),('седьмого','7-го')]:s=s.replace(a,b)
 return re.sub(r'\s+([,.])',r'\1',s)
